#include <cuda_runtime.h>
#include <cstdio>
typedef unsigned int uint;
#include "sizeof-byte-surface.cu"
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){printf("CUDA ERROR %s\n",cudaGetErrorString(e));return 2;}}while(0)
int main(){uint values[]={0,1,0x10000000,0x7fffffff,0xffffffff},sizes[20],*input,*out;CHECK(cudaMalloc(&input,20));CHECK(cudaMalloc(&out,256*4));CHECK(cudaMemcpy(input,values,20,cudaMemcpyHostToDevice));sizeProbe<<<1,32>>>(input,out);CHECK(cudaMemcpy(sizes,out,80,cudaMemcpyDeviceToHost));for(int i=0;i<5;i++){size_t product=size_t(values[i])*16;uint expected[]={uint(product),product>4294967295u,12,24};for(int j=0;j<4;j++)if(sizes[i*4+j]!=expected[j])return 1;}cudaArray_t array;auto desc=cudaCreateChannelDesc<unsigned char>();CHECK(cudaMalloc3DArray(&array,&desc,make_cudaExtent(8,8,4),cudaArraySurfaceLoadStore));cudaResourceDesc resource={};resource.resType=cudaResourceTypeArray;resource.res.array.array=array;cudaSurfaceObject_t surface;cudaTextureObject_t texture;CHECK(cudaCreateSurfaceObject(&surface,&resource));cudaTextureDesc t={};t.normalizedCoords=1;t.filterMode=cudaFilterModeLinear;t.readMode=cudaReadModeNormalizedFloat;t.addressMode[0]=t.addressMode[1]=t.addressMode[2]=cudaAddressModeWrap;CHECK(cudaCreateTextureObject(&texture,&resource,&t,nullptr));byteWrite<<<dim3(2,2,2),dim3(4,4,2)>>>(surface);byteRead<<<dim3(2,2,2),dim3(4,4,2)>>>(texture,out);uint actual[256];CHECK(cudaMemcpy(actual,out,sizeof(actual),cudaMemcpyDeviceToHost));for(int i=0;i<256;i++)if(actual[i]!=i)return 1;CHECK(cudaDestroySurfaceObject(surface));CHECK(cudaDestroyTextureObject(texture));CHECK(cudaFreeArray(array));CHECK(cudaFree(input));CHECK(cudaFree(out));printf("PASS 20 sizeof/multiplication results and all 256 byte surface values sampled on GPU\n");}
